fn solve(input: Vec<char>) -> Vec<char> {
    // According to the problem statement, input.len() >= 3,
    // input[1] == ' ', and input[0], input[2] ∈ {'H', 'D'}.
    // We compare input[0] and input[2]. If they match, output ['H','\n'],
    // otherwise ['D','\n'].

    let first = input[0];
    let third = input[2];

    let mut output = Vec::with_capacity(2);
    if first == third {
        output.push('H');
    } else {
        output.push('D');
    }
    output.push('\n');

    output
}

